import Foundation

public protocol TranscriptReadRepository: Sendable {
    func searchTranscripts(query: String, limit: Int?, offset: Int?) async throws -> [RecordingSummary]
    func getTranscriptDraft(for id: RecordingID) async throws -> String?
}

extension TranscriptReadRepository {
    public func searchTranscripts(query: String) async throws -> [RecordingSummary] {
        return try await searchTranscripts(query: query, limit: nil, offset: nil)
    }

    /// Default implementation returns `nil`. Conformers backed by persistent storage
    /// should override this to return a previously saved draft.
    public func getTranscriptDraft(for id: RecordingID) async throws -> String? {
        return nil
    }
}

extension TranscriptWriteRepository {
    /// Default implementation is a no-op. Conformers backed by persistent storage
    /// should override this to persist the draft text.
    public func saveDraftTranscript(draftText: String, for id: RecordingID) async throws {}
}

public protocol TranscriptWriteRepository: Sendable {
    func updateTranscript(id: RecordingID, transcript: TranscriptionResult) async throws
    func saveDraftTranscript(draftText: String, for id: RecordingID) async throws
}

public typealias TranscriptRepository = TranscriptReadRepository & TranscriptWriteRepository

