7	public actor DuckDBReaderActor: DiarizationReadRepository, NotesReadRepository, RecordingReadRepository, SummaryReadRepository, TranscriptReadRepository {
8	    private let storageQueue = DispatchSerialQueue(label: "app.the-record.duckdb", qos: .utility)
9	    public nonisolated var unownedExecutor: UnownedSerialExecutor {
10	        storageQueue.asUnownedSerialExecutor()
11	    }
12	
13	    public let database: Database
14	    // internal (not private): DuckDBReaderActorAdmin.swift accesses these via a cross-file
15	    // extension in the same module. Swift private is file-scoped; actor isolation is the
16	    // actual safety boundary here.
17	    let connection: Connection
18	    let logger = AppLogger.for(category: "DuckDBStorage")
19	
20	    public init(databasePath: URL?) throws {
21	        do {
22	            let store: Database.Store = if let path = databasePath {
23	                .file(at: path)
24	            } else {
25	                .inMemory
26	            }
27	            database = try DuckDBInit.openDatabase(store: store)
28	            connection = try database.connect()
29	            try Self.setupSchema(connection: connection)
30	        } catch {
31	            print("DUCKDB INIT ERROR: \(error)")
32	            throw StorageError.readFailed(underlying: error)
33	        }
34	    }
35	
36	    private static func setupSchema(connection: Connection) throws {
37	        // Required DDL statements — any failure is fatal.
38	        try executeRequired(connection: connection, sql: DuckDBSQL.createRecordings, label: "createRecordings")
39	        try executeRequired(connection: connection, sql: DuckDBSQL.createSegments, label: "createSegments")
40	        try executeRequired(connection: connection, sql: DuckDBSQL.createCommitmentsTable, label: "createCommitmentsTable")
41	        try executeRequired(connection: connection, sql: DuckDBSQL.createMeetingNotes, label: "createMeetingNotes")
42	        try executeRequired(connection: connection, sql: DuckDBSQL.createSummaries, label: "createSummaries")
43	        try executeRequired(connection: connection, sql: DuckDBSQL.createRecordingsIndex, label: "createRecordingsIndex")
44	
45	        // Additive migrations — tolerate "already exists" / "duplicate" / "reason: nil" errors.
46	        // Migration for existing databases: add is_pending if not present.
47	        try executeMigration(connection: connection, sql: DuckDBSQL.addIsPendingColumn, label: "addIsPendingColumn")
48	        // Migration for Epic 21: add word_timings VARCHAR column to diarized_segments if not present.
49	        try executeMigration(connection: connection, sql: DuckDBSQL.addWordTimingsColumn, label: "addWordTimingsColumn")
50	        // Migration for epic-28 / task-003: add cleaned_mic_audio_url column if not present.
51	        try executeMigration(connection: connection, sql: DuckDBSQL.addCleanedMicAudioUrlColumn, label: "addCleanedMicAudioUrlColumn")
52	
53	        try executeRequired(connection: connection, sql: DuckDBSQL.createInferenceTelemetry, label: "createInferenceTelemetry")
54	
55	        // Bump schema version to reflect the legacy DDL baseline so the migration runner
56	        // skips steps v0→v4 (already applied above) and only runs pending steps above v4.
57	        try connection.execute(DuckDBSQL.createSchemaVersion)
58	        let versionResult = try connection.query(DuckDBSQL.readSchemaVersion)
59	        let currentVersion: Int32 = versionResult.rowCount > 0
60	            ? (versionResult[0].cast(to: Int32.self)[0] ?? 0)
61	            : 0
62	        if currentVersion < 4 {
63	            try connection.execute(DuckDBSQL.setSchemaVersion(4))
64	        }
65	        do {
66	            try DuckDBMigrationRunner().migrate(connection: connection)
67	        } catch {
68	            // Revert the baseline bump so the next startup can retry rather than boot-loop.
69	            if currentVersion < 4 {
70	                try? connection.execute(DuckDBSQL.setSchemaVersion(currentVersion))
71	            }
72	            throw error
73	        }
74	    }
75	
76	    /// Executes a DDL statement that must succeed — any error is fatal.
77	    private static func executeRequired(connection: Connection, sql: String, label: String) throws {
78	        do {
79	            try connection.execute(sql)
80	        } catch {
81	            print("FAILED \(label): \(error)")
82	            throw error
83	        }
84	    }
85	
86	    /// Executes an additive migration statement. Errors that indicate the column/table already
87	    /// exists ("exists", "duplicate", "reason: nil") are silently swallowed; others are rethrown.
88	    private static func executeMigration(connection: Connection, sql: String, label: String) throws {
89	        do {
90	            try connection.execute(sql)
91	        } catch {
92	            print("FAILED \(label): \(error)")
93	            let desc = String(describing: error).lowercased()
94	            if !desc.contains("exists"), !desc.contains("duplicate"), !desc.contains("reason: nil") {
95	                throw error
96	            }
97	        }
98	    }
99	
100	    public init() throws {
101	        let dbDir = Directories.appSupport
102	        try Directories.ensureDirectory(at: dbDir)
103	        let dbURL = dbDir.appendingPathComponent(AppConstants.Paths.databaseFileName)
104	        try self.init(databasePath: dbURL)
105	    }
106	
107	    // MARK: - Prepared Statement Helper
108	
109	    func prepared(_ sql: String) throws -> PreparedStatement {
110	        try PreparedStatement(connection: connection, query: sql)
111	    }
112	}
