import Domain
import DuckDB
import Foundation
import Logging

// MARK: - Database path registry

/// Thread-safe global registry mapping `Database` identity → file URL.
/// Populated by `DuckDBReaderActor.init(databasePath:)` so that
/// `DuckDBWriterActor.backupDatabase(to:)` can resolve the source path
/// even when the writer was constructed with only a `Database` reference.
enum DatabasePathRegistry {
    private static let lock = NSLock()
    // nonisolated(unsafe): access is fully serialized by `lock` above.
    private nonisolated(unsafe) static var store: [ObjectIdentifier: URL] = [:]

    static func register(database: Database, path: URL) {
        lock.withLock { store[ObjectIdentifier(database)] = path }
    }

    static func path(for database: Database) -> URL? {
        lock.withLock { store[ObjectIdentifier(database)] }
    }
}

// MARK: - DuckDBWriterActor

public actor DuckDBWriterActor: RecordingWriteRepository, DiarizationWriteRepository, NotesWriteRepository, SummaryWriteRepository, TranscriptWriteRepository, WordTimingsWriteRepository {
    private let writeQueue = DispatchSerialQueue(label: "app.the-record.duckdb.writer", qos: .userInitiated)
    public nonisolated var unownedExecutor: UnownedSerialExecutor {
        writeQueue.asUnownedSerialExecutor()
    }

    let database: Database
    let connection: Connection
    let logger = AppLogger.for(category: "DuckDBWriter")

    /// The file URL of the database backing store, or `nil` for in-memory databases.
    /// First consulted by `backupDatabase(to:)` before falling back to `duckdb_databases()`.
    let databasePath: URL?

    public init(database: Database, databasePath: URL? = nil) throws {
        self.database = database
        self.databasePath = databasePath
        do {
            self.connection = try database.connect()
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
    }

    func prepared(_ sql: String) throws -> PreparedStatement {
        try PreparedStatement(connection: connection, query: sql)
    }

}

// MARK: - Backup

public extension DuckDBWriterActor {

    /// Backs up the writer's own database file to `destination`.
    ///
    /// Issues CHECKPOINT to flush the WAL before copying so the on-disk file
    /// is consistent. Overwrites any existing file at `destination` (single-generation).
    ///
    /// - Throws: `StorageError.writeFailed` when the database is in-memory (no
    ///   file path) or when the file copy fails. Errors are catchable — callers
    ///   should log and continue rather than crashing (best-effort backup).
    func backupDatabase(to destination: URL) async throws {
        try connection.execute("CHECKPOINT")

        let source: URL
        if let explicit = databasePath {
            source = explicit
        } else {
            // Fall back to duckdb_databases() introspection when no explicit path was given.
            let result = try connection.query(
                "SELECT path FROM duckdb_databases() WHERE path != '' LIMIT 1"
            )
            guard result.rowCount > 0 else {
                throw StorageError.writeFailed(underlying: nil)
            }
            let filePaths = result[0].cast(to: String.self)
            guard let rawPath = filePaths[0], !rawPath.isEmpty else {
                throw StorageError.writeFailed(underlying: nil)
            }
            source = URL(fileURLWithPath: rawPath)
        }
        try Self.copyFile(from: source, to: destination)
    }

    /// Backs up an arbitrary `source` database file to `destination`.
    ///
    /// The writer actor holds the exclusive write lock during the copy.
    /// CHECKPOINT is attempted as a best-effort WAL flush — failure is logged
    /// internally and does not abort the backup (the caller's source file may
    /// belong to a different database instance).
    /// Overwrites any existing file at `destination` (single-generation).
    func backupDatabase(source: URL, to destination: URL) async throws {
        // Best-effort WAL flush; ignore failure — source may not be our database.
        try? connection.execute("CHECKPOINT")
        try Self.copyFile(from: source, to: destination)
    }

    // MARK: - Private helpers

    private static func copyFile(from source: URL, to destination: URL) throws {
        let fm = FileManager.default
        // Remove any existing backup before copying (single-generation — no rotation).
        if fm.fileExists(atPath: destination.path) {
            do {
                try fm.removeItem(at: destination)
            } catch {
                throw StorageError.writeFailed(underlying: error)
            }
        }
        do {
            try fm.copyItem(at: source, to: destination)
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
    }
}

import Foundation

/// Capability protocol for persisting word-level timing data for transcription segments.
///
/// Conforming types write back the word timings produced by alignment engines
/// (e.g. ``DTWWordAligner``) so that the data is available to the UI layer and
/// to downstream consumers (export, karaoke highlighting, acoustic scrubbing).
///
/// This is a narrow write-only protocol — reading segments back is handled by
/// ``RecordingReadRepository`` which returns ``StoredRecording/transcript``.
public protocol WordTimingsWriteRepository: Sendable {
    /// Persists the word-level timing data for the given segments of a recording.
    ///
    /// Implementations must update only the `wordTimings` field of each segment;
    /// other segment fields (text, confidence, times) must not be modified.
    ///
    /// - Parameters:
    ///   - recordingId: The recording whose segments are being updated.
    ///   - segments: The full set of updated ``TranscriptionSegment`` values,
    ///     each carrying populated `wordTimings` where alignment succeeded.
    func saveWordTimings(recordingId: RecordingID, segments: [TranscriptionSegment]) async throws
}

// NOT DEAD CODE — pre-built DuckDB-backed cache for CachingContextProvider. Ships with MCP caching.

import Accelerate
import Domain
import DuckDB
import Foundation
import Logging
@preconcurrency import NaturalLanguage

public actor DuckDBContextCache {
    private let cacheQueue = DispatchSerialQueue(label: "app.the-record.contextcache", qos: .utility)
    public nonisolated var unownedExecutor: UnownedSerialExecutor {
        cacheQueue.asUnownedSerialExecutor()
    }

    private let database: Database
    private let connection: Connection
    private let logger = AppLogger.for(category: "ContextCache")
    private var nlEmbedding: NLEmbedding?

    public init(databasePath: URL?) throws {
        let store: Database.Store = if let path = databasePath {
            .file(at: path)
        } else {
            .inMemory
        }
        database = try DuckDBInit.openDatabase(store: store)
        connection = try database.connect()
        try setupSchema(connection: connection)
    }

    private nonisolated func setupSchema(connection: Connection) throws {
        try connection.execute(Self.createTable)
    }

    /// Looks up cached results for the given `query` and `providerID`.
    ///
    /// The cache is keyed on `(query_text, provider_id)` together (ISOL-001).
    /// A hit for provider A is never returned for provider B even when the query
    /// text is identical — preventing cross-provider contamination (F6/#195).
    public func get(query: String, providerID: String, ttlSeconds: Int) throws -> [CachedResult]? {
        let stmt = try PreparedStatement(
            connection: connection,
            query: Self.selectCached
        )
        try stmt.bind(query, at: 1)
        try stmt.bind(providerID, at: 2)
        try stmt.bind(Int32(ttlSeconds), at: 3)
        let result = try stmt.execute()
        guard result.rowCount > 0 else { return nil }

        let titles = result[0].cast(to: String.self)
        let bodies = result[1].cast(to: String.self)
        let urls = result[2].cast(to: String.self)
        let providerIDs = result[3].cast(to: String.self)
        let scores = result[4].cast(to: Double.self)

        var results: [CachedResult] = []
        for i in 0 ..< result.rowCount {
            guard let title = titles[i], let body = bodies[i],
                  let pid = providerIDs[i], let score = scores[i] else { continue }
            results.append(CachedResult(
                title: title, body: body,
                sourceURL: urls[i], providerID: pid,
                relevanceScore: score
            ))
        }
        return results
    }

    /// Stores `results` in the cache, keyed on `(query_text, provider_id)`.
    ///
    /// - Parameters:
    ///   - query: The query text to cache results for.
    ///   - results: The results to store. Each result carries its own `providerID`.
    ///   - emptyProviderID: Provider ID to use when `results` is empty (sentinel record).
    ///     Pass the provider's ID so the empty-result record is scoped to that provider.
    public func put(query: String, results: [CachedResult], emptyProviderID: String = "") async throws {
        // Delete only entries for the providers present in the new result set so
        // other providers' entries for the same query_text are not evicted (ISOL-001).
        let providerIDsToEvict: Set<String> = results.isEmpty
            ? (emptyProviderID.isEmpty ? [] : [emptyProviderID])
            : Set(results.map(\.providerID))

        for pid in providerIDsToEvict {
            let delStmt = try PreparedStatement(connection: connection, query: Self.deleteCached)
            try delStmt.bind(query, at: 1)
            try delStmt.bind(pid, at: 2)
            _ = try delStmt.execute()
        }

        let embeddingBlob: Data? = await embeddingVector(for: query).map { vector in
            vector.withUnsafeBufferPointer { Data(buffer: $0) }
        }

        guard !results.isEmpty else {
            // Empty-result sentinel: record that this provider returned nothing so we
            // don't re-query until the TTL expires (ISOL-001 compatible: scoped to provider).
            let emptyStmt = try PreparedStatement(connection: connection, query: Self.insertCached)
            try emptyStmt.bind(query, at: 1)
            try emptyStmt.bind("", at: 2)
            try emptyStmt.bind("", at: 3)
            try emptyStmt.bind(String?.none, at: 4)
            try emptyStmt.bind(emptyProviderID, at: 5)
            try emptyStmt.bind(0.0, at: 6)
            try emptyStmt.bind(embeddingBlob, at: 7)
            _ = try emptyStmt.execute()
            return
        }

        let stmt = try PreparedStatement(connection: connection, query: Self.insertCached)
        for r in results {
            try stmt.bind(query, at: 1)
            try stmt.bind(r.title, at: 2)
            try stmt.bind(r.body, at: 3)
            try stmt.bind(r.sourceURL, at: 4)
            try stmt.bind(r.providerID, at: 5)
            try stmt.bind(r.relevanceScore, at: 6)
            try stmt.bind(embeddingBlob, at: 7)
            _ = try stmt.execute()
        }
    }

    // swiftlint:disable:next cyclomatic_complexity
    public func getSemantic(
        query: String,
        providerID: String,
        matcher: SemanticCacheMatcher,
        threshold: Double,
        ttlSeconds: Int
    ) async throws -> [CachedResult]? {
        let stmt = try PreparedStatement(connection: connection, query: Self.selectDistinctQueriesWithEmbeddings)
        try stmt.bind(providerID, at: 1)
        let result = try stmt.execute()
        guard result.rowCount > 0 else { return nil }

        let queries = result[0].cast(to: String.self)
        let embeddings = result[1].cast(to: Data.self)

        // Compute query embedding once
        guard let queryVector = await embeddingVector(for: query) else {
            // Fall back to text-based matcher when embedding unavailable
            var bestMatch: (query: String, score: Double)?
            for i in 0 ..< result.rowCount {
                guard let cached = queries[i] else { continue }
                let score = matcher.similarity(between: query, and: cached)
                if score >= threshold, bestMatch.map({ score > $0.score }) ?? true {
                    bestMatch = (cached, score)
                }
            }
            guard let match = bestMatch else { return nil }
            return try get(query: match.query, providerID: providerID, ttlSeconds: ttlSeconds)
        }

        // Pre-filter with vDSP cosine similarity (O(N) vector ops, no ML inference).
        // Use a low pre-filter threshold so no true matches are dropped; verify
        // candidates with matcher.similarity() to preserve numerical compatibility
        // with the NLEmbedding distance scale used elsewhere.
        let preFilterThreshold = max(0.0, threshold - 0.3)
        var candidates: [(query: String, score: Double)] = []

        for i in 0 ..< result.rowCount {
            guard let cached = queries[i], let blob = embeddings[i] else { continue }
            let storedVector: [Double] = blob.withUnsafeBytes {
                Array($0.bindMemory(to: Double.self))
            }
            let coarse = cosineSimilarity(queryVector, storedVector)
            if coarse >= preFilterThreshold {
                candidates.append((cached, coarse))
            }
        }

        guard !candidates.isEmpty else { return nil }

        // Verify candidates with the calibrated NLEmbedding matcher.
        var bestMatch: (query: String, score: Double)?
        for candidate in candidates {
            let score = matcher.similarity(between: query, and: candidate.query)
            if score >= threshold, bestMatch == nil || score > bestMatch!.score {
                bestMatch = (candidate.query, score)
            }
        }

        guard let match = bestMatch else { return nil }
        return try get(query: match.query, providerID: providerID, ttlSeconds: ttlSeconds)
    }

    public func pruneIfNeeded(maxEntries: Int) throws {
        let countResult = try connection.query(Self.countAll)
        let count = countResult[0].cast(to: Int64.self)[0] ?? 0
        guard count > Int64(maxEntries) else { return }
        let excess = count - Int64(maxEntries)
        let stmt = try PreparedStatement(
            connection: connection,
            query: Self.pruneOldest
        )
        try stmt.bind(excess, at: 1)
        _ = try stmt.execute()
        logger
            .info(
                // swiftlint:disable:next line_length
                "Pruned \(excess, privacy: .public) stale context cache entries (\(count, privacy: .public) → \(maxEntries, privacy: .public))"
            )
    }

    public func entryCount() throws -> Int {
        let result = try connection.query(Self.countAll)
        return Int(result[0].cast(to: Int64.self)[0] ?? 0)
    }

    // MARK: - SQL

    private static let createTable = """
    CREATE TABLE IF NOT EXISTS context_cache (
        query_text VARCHAR NOT NULL,
        title VARCHAR NOT NULL,
        body VARCHAR NOT NULL,
        source_url VARCHAR,
        provider_id VARCHAR NOT NULL,
        relevance_score DOUBLE NOT NULL DEFAULT 0,
        cached_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        embedding BLOB
    )
    """

    // Cache lookup is keyed on (query_text, provider_id) to prevent cross-provider
    // contamination (ISOL-001 / F6/#195). $1 = query_text, $2 = provider_id, $3 = ttl seconds.
    private static let selectCached = """
    SELECT title, body, source_url, provider_id, relevance_score
    FROM context_cache
    WHERE query_text = $1
    AND provider_id = $2
    AND EPOCH(CURRENT_TIMESTAMP - cached_at) < $3
    ORDER BY relevance_score DESC
    """

    // $1 = provider_id — scoped to prevent cross-provider embedding leakage (ISOL-001).
    private static let selectDistinctQueriesWithEmbeddings =
        "SELECT DISTINCT query_text, embedding FROM context_cache WHERE provider_id = $1"

    // Scoped delete: removes only entries for the given (query_text, provider_id) pair.
    // $1 = query_text, $2 = provider_id.
    private static let deleteCached =
        "DELETE FROM context_cache WHERE query_text = $1 AND provider_id = $2"

    private static let insertCached = """
    INSERT INTO context_cache (query_text, title, body, source_url, provider_id, relevance_score, embedding) \
    VALUES ($1, $2, $3, $4, $5, $6, $7)
    """

    private static let countAll = "SELECT COUNT(*) FROM context_cache"

    private static let pruneOldest =
        "DELETE FROM context_cache WHERE rowid IN (SELECT rowid FROM context_cache ORDER BY cached_at ASC LIMIT $1)"

    // MARK: - Embedding helpers

    private func embeddingVector(for text: String) async -> [Double]? {
        if nlEmbedding == nil {
            nlEmbedding = await Task.detached(priority: .utility) {
                NLEmbedding.sentenceEmbedding(for: .english)
            }.value
        }
        return nlEmbedding?.vector(for: text)
    }

    private func cosineSimilarity(_ a: [Double], _ b: [Double]) -> Double {
        guard a.count == b.count, !a.isEmpty else { return 0 }
        let dot = vDSP.dot(a, b)
        let magA = vDSP.sumOfSquares(a).squareRoot()
        let magB = vDSP.sumOfSquares(b).squareRoot()
        guard magA > 0, magB > 0 else { return 0 }
        return dot / (magA * magB)
    }
}

public struct CachedResult: Sendable {
    public let title: String
    public let body: String
    public let sourceURL: String?
    public let providerID: String
    public let relevanceScore: Double
}

import Domain
import DuckDB
import Foundation
import Logging

// Error Translation Matrix:
//   DuckDB init/connect/execute/query errors → StorageError.readFailed  (init, query ops)
//   DuckDB execute errors on writes          → StorageError.writeFailed
//
// Thread Safety:
//   actor-isolated — all state (database, connection) accessed only through actor.

public actor DuckDBCommitmentStore: CommitmentStore {
    private let database: Database
    private let connection: Connection
    private let logger = AppLogger.for(category: "DuckDBCommitments")

    // MARK: - Init

    public init(databasePath: URL?) throws {
        do {
            let store: Database.Store = if let path = databasePath {
                .file(at: path)
            } else {
                .inMemory
            }
            database = try DuckDBInit.openDatabase(store: store)
            connection = try database.connect()
            try setupSchema(connection: connection)
        } catch {
            throw StorageError.readFailed(underlying: error)
        }
    }

    private nonisolated func setupSchema(connection: Connection) throws {
        try connection.execute(DuckDBSQL.createCommitmentsTable)
        try connection.execute(DuckDBSQL.createCommitmentsStatusIndex)
        try connection.execute(DuckDBSQL.createCommitmentsMeetingIndex)
    }

    // MARK: - Prepared Statement Helper

    private func prepared(_ sql: String) throws -> PreparedStatement {
        try PreparedStatement(connection: connection, query: sql)
    }

    // MARK: - CommitmentStore

    public func record(_ commitment: Commitment) async throws {
        let iso = commitment.createdAt.formatted(Date.ISO8601FormatStyle(includingFractionalSeconds: true))
        let dueDateStr: String? = commitment.dueDate.map {
            $0.formatted(.iso8601.year().month().day())
        }
        do {
            let stmt = try prepared(DuckDBSQL.insertCommitment)
            try stmt.bind(commitment.id.rawValue, at: 1)
            try stmt.bind(commitment.description, at: 2)
            try stmt.bind(commitment.assignee, at: 3)
            try stmt.bind(dueDateStr, at: 4)
            try stmt.bind(commitment.status.rawValue, at: 5)
            try stmt.bind(commitment.meetingId.rawValue, at: 6)
            try stmt.bind(iso, at: 7)
            _ = try stmt.execute()
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
        logger.info("Recorded commitment \(commitment.id, privacy: .private)")
    }

    public func openCommitments() async throws -> [Commitment] {
        let result: ResultSet
        do {
            result = try connection.query(DuckDBSQL.selectOpenCommitments)
        } catch {
            throw StorageError.readFailed(underlying: error)
        }
        return decodeCommitments(from: result)
    }

    public func commitments(for meetingId: RecordingID) async throws -> [Commitment] {
        let result: ResultSet
        do {
            let stmt = try prepared(DuckDBSQL.selectCommitmentsForMeeting)
            try stmt.bind(meetingId.rawValue, at: 1)
            result = try stmt.execute()
        } catch {
            throw StorageError.readFailed(underlying: error)
        }
        return decodeCommitments(from: result)
    }

    // MARK: - Private

    private func decodeCommitments(from result: ResultSet) -> [Commitment] {
        guard result.rowCount > 0 else { return [] }
        let ids = result[0].cast(to: String.self)
        let descs = result[1].cast(to: String.self)
        let assignees = result[2].cast(to: String.self)
        let dueDates = result[3].cast(to: String.self)
        let statuses = result[4].cast(to: String.self)
        let meetingIds = result[5].cast(to: String.self)
        let createdAts = result[6].cast(to: String.self)
        var out: [Commitment] = []
        for i in 0 ..< result.rowCount {
            guard let id = ids[i], let desc = descs[i],
                  let statusRaw = statuses[i], let mid = meetingIds[i],
                  let createdStr = createdAts[i],
                  let status = CommitmentStatus(rawValue: statusRaw),
                  let createdAt = try? Date(
                      createdStr,
                      strategy: Date.ISO8601FormatStyle(includingFractionalSeconds: true)
                  ) else { continue }
            out.append(Commitment(
                id: CommitmentID(id), description: desc,
                assignee: assignees[i],
                dueDate: dueDates[i].flatMap { try? Date($0, strategy: .iso8601.year().month().day()) },
                status: status,
                meetingId: RecordingID(mid),
                createdAt: createdAt
            ))
        }
        return out
    }
}

import Domain
import DuckDB
import Foundation

// MARK: - MigrationStep

/// A single versioned, named schema migration step.
public struct MigrationStep: Sendable {
    /// Human-readable name for logging and diagnostics.
    public let name: String

    /// The schema version the database must be at before this step can run.
    public let fromVersion: Int32

    /// The schema version the database will be at after this step runs successfully.
    public let toVersion: Int32

    /// The migration closure. Receives an open `Connection` and must apply schema changes.
    /// Throwing here will cause the runner to roll back and rethrow as `StorageError.migrationFailed`.
    public let migrate: @Sendable (Connection) throws -> Void

    public init(
        name: String,
        fromVersion: Int32,
        toVersion: Int32,
        migrate: @escaping @Sendable (Connection) throws -> Void
    ) {
        self.name = name
        self.fromVersion = fromVersion
        self.toVersion = toVersion
        self.migrate = migrate
    }
}

// MARK: - DuckDBMigrationRunner

/// Executes versioned, ordered, idempotent schema migrations against a DuckDB connection.
///
/// Schema version is tracked via a `schema_version` table (DuckDB has no PRAGMA user_version).
/// On each `migrate(connection:)` call, only steps whose `fromVersion` matches the current version
/// are applied — already-applied steps are skipped.
///
/// Each step is wrapped in a BEGIN/ROLLBACK transaction. If a step throws, the transaction is
/// rolled back and `StorageError.migrationFailed` is thrown — leaving the schema version unchanged.
public final class DuckDBMigrationRunner: Sendable {

    // MARK: - Public state

    /// Ordered list of migration steps this runner will apply.
    public let steps: [MigrationStep]

    /// The schema version that a fully-migrated database should be at.
    public var currentSchemaVersion: Int32 {
        steps.last?.toVersion ?? 0
    }

    /// Versions applied during the most recent `migrate(connection:)` call (ascending order).
    /// Protected by the serial nature of `migrate` — callers must `await` before reading.
    public nonisolated(unsafe) private(set) var appliedVersions: [Int32] = []

    // MARK: - Init

    /// Creates a runner with an explicit set of steps (primarily for testing).
    public init(steps: [MigrationStep]) {
        self.steps = steps
    }

    /// Creates a runner with the production migration plan.
    public convenience init() {
        self.init(steps: DuckDBMigrationRunner.productionSteps)
    }

    // MARK: - migrate

    /// Applies all pending migrations to `connection` in ascending version order.
    ///
    /// Each step is wrapped in an explicit transaction. On failure the transaction is rolled
    /// back and `StorageError.migrationFailed` is thrown. The schema version table is updated
    /// inside the same transaction so it stays in sync.
    ///
    /// Calling `migrate` again after a successful run is a no-op.
    public func migrate(connection: Connection) throws {
        // Ensure schema_version table exists before any reads or writes.
        try connection.execute(DuckDBSQL.createSchemaVersion)

        var applied: [Int32] = []

        for step in steps {
            let currentVersion = try readSchemaVersion(connection: connection)

            // Skip steps that have already been applied.
            guard currentVersion == step.fromVersion else {
                continue
            }

            // Each step runs inside a transaction so partial DDL can be rolled back.
            do {
                try connection.execute("BEGIN TRANSACTION")
                try step.migrate(connection)
                try connection.execute(DuckDBSQL.setSchemaVersion(step.toVersion))
                try connection.execute("COMMIT")
                applied.append(step.toVersion)
            } catch {
                // Roll back the partial work and re-throw as a StorageError.
                try? connection.execute("ROLLBACK")
                throw StorageError.migrationFailed(underlying: AnyError(error))
            }
        }

        appliedVersions = applied
    }

    // MARK: - Helpers

    private func readSchemaVersion(connection: Connection) throws -> Int32 {
        let result = try connection.query(DuckDBSQL.readSchemaVersion)
        guard result.rowCount > 0 else { return 0 }
        return result[0].cast(to: Int32.self)[0] ?? 0
    }
}

// MARK: - AnyError (Sendable wrapper)

/// Wraps any non-Sendable error to satisfy `StorageError.migrationFailed(underlying:)`.
private struct AnyError: Error, Sendable {
    let message: String
    init(_ error: any Error) {
        self.message = error.localizedDescription
    }
}

// MARK: - Production migration plan

extension DuckDBMigrationRunner {
    /// The ordered list of production schema migrations.
    ///
    /// Version history:
    ///   v0 → v1 : Create core tables (recordings, diarized_segments, summaries, meeting_notes,
    ///             commitments, inference_telemetry) + indexes
    ///   v1 → v2 : Add `is_pending` column to recordings
    ///   v2 → v3 : Add `word_timings` column to diarized_segments
    ///   v3 → v4 : Add `cleaned_mic_audio_url` column to recordings (epic-28)
    static let productionSteps: [MigrationStep] = [
        MigrationStep(
            name: "v0→v1: create-core-tables",
            fromVersion: 0,
            toVersion: 1,
            migrate: { conn in
                try conn.execute(DuckDBSQL.createRecordings)
                try conn.execute(DuckDBSQL.createSegments)
                try conn.execute(DuckDBSQL.createSummaries)
                try conn.execute(DuckDBSQL.createMeetingNotes)
                try conn.execute(DuckDBSQL.createCommitmentsTable)
                try conn.execute(DuckDBSQL.createInferenceTelemetry)
                try conn.execute(DuckDBSQL.createRecordingsIndex)
                try conn.execute(DuckDBSQL.createCommitmentsStatusIndex)
                try conn.execute(DuckDBSQL.createCommitmentsMeetingIndex)
            }
        ),
        MigrationStep(
            name: "v1→v2: add-is-pending-column",
            fromVersion: 1,
            toVersion: 2,
            migrate: { conn in
                try conn.execute(DuckDBSQL.addIsPendingColumn)
            }
        ),
        MigrationStep(
            name: "v2→v3: add-word-timings-column",
            fromVersion: 2,
            toVersion: 3,
            migrate: { conn in
                try conn.execute(DuckDBSQL.addWordTimingsColumn)
            }
        ),
        MigrationStep(
            name: "v3→v4: add-cleaned-mic-audio-url-column",
            fromVersion: 3,
            toVersion: 4,
            migrate: { conn in
                try conn.execute(DuckDBSQL.addCleanedMicAudioUrlColumn)
            }
        ),
        MigrationStep(
            name: "v4→v5: add-needs-retranscription-column",
            fromVersion: 4,
            toVersion: 5,
            migrate: { conn in
                try conn.execute(DuckDBSQL.addNeedsRetranscriptionColumn)
            }
        ),
        MigrationStep(
            name: "v5->v6: add-transcript-draft-column",
            fromVersion: 5,
            toVersion: 6,
            migrate: { conn in
                try conn.execute(DuckDBSQL.addTranscriptDraftColumn)
            }
        ),
    ]
}

