import Domain
import DuckDB
import Foundation
import Utilities

public extension DuckDBWriterActor {
    func saveRecording(_ file: AudioFile) async throws -> StoredRecording {
        guard !file.id.rawValue.isEmpty else {
            throw StorageError.invalidFile(reason: "AudioFile.id must not be empty")
        }
        let iso = file.recordedAt.formatted(Date.ISO8601FormatStyle(includingFractionalSeconds: true))
        do {
            let stmt = try prepared(DuckDBSQL.insertRecording)
            try stmt.bind(file.id.rawValue, at: 1)
            try stmt.bind(iso, at: 2)
            try stmt.bind(file.duration, at: 3)
            try stmt.bind(Int64(file.fileSize), at: 4)
            try stmt.bind(file.url.absoluteString, at: 5)
            try stmt.bind("", at: 6)
            try stmt.bind(0.0, at: 7)
            try stmt.bind("none", at: 8)
            try stmt.bind(Int32(0), at: 9)
            try stmt.bind(Int32(0), at: 10)
            try stmt.bind(0.0, at: 11)
            try stmt.bind(String?.none, at: 12)
            _ = try stmt.execute()
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
        let meta = RecordingMetadata(
            id: file.id, recordedAt: file.recordedAt, duration: file.duration,
            fileSize: file.fileSize, audioURL: file.url, transcriptURL: nil,
            modelId: ModelID(""), processingTime: 0, computeUnit: .unknown, wordCount: 0
        )
        logger.info("Saved recording \(file.id, privacy: .private) to DuckDB")
        return StoredRecording(metadata: meta)
    }

    func markSessionStarted(id: RecordingID, startedAt: Foundation.Date) async throws {
        let iso = startedAt.formatted(Date.ISO8601FormatStyle(includingFractionalSeconds: true))
        do {
            let stmt = try prepared(DuckDBSQL.insertPendingSession)
            try stmt.bind(id.rawValue, at: 1)
            try stmt.bind(iso, at: 2)
            _ = try stmt.execute()
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
    }

    func updateCleanedMicPath(id: RecordingID, path: URL?) async throws {
        guard let path else { return }
        do {
            let stmt = try prepared(DuckDBSQL.updateCleanedMicPath)
            try stmt.bind(path.absoluteString, at: 1)
            try stmt.bind(id.rawValue, at: 2)
            _ = try stmt.execute()
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
    }

    func markNeedsRetranscription(id: RecordingID, audioURL: URL) async throws {
        do {
            let stmt = try prepared(DuckDBSQL.markNeedsRetranscription)
            try stmt.bind(id.rawValue, at: 1)
            _ = try stmt.execute()
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
        logger.info("Marked recording \(id, privacy: .private) as needs-retranscription (#116); WAV: \(audioURL.lastPathComponent, privacy: .public)")
    }

    func updateAudioDuration(id: RecordingID, duration: Double, fileSize: Int) async throws {
        do {
            let stmt = try prepared("UPDATE recordings SET duration = $1, file_size = $2 WHERE id = $3")
            try stmt.bind(duration, at: 1)
            try stmt.bind(Int64(fileSize), at: 2)
            try stmt.bind(id.rawValue, at: 3)
            _ = try stmt.execute()
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
    }

    func deleteRecording(id: RecordingID) async throws {
        let check: ResultSet
        do {
            let stmt = try prepared(DuckDBSQL.selectAudioURL)
            try stmt.bind(id.rawValue, at: 1)
            check = try stmt.execute()
        } catch {
            throw StorageError.readFailed(underlying: error)
        }
        guard check.rowCount > 0 else {
            throw StorageError.recordingNotFound(id: id)
        }
        let audioURL = check[0].cast(to: String.self)[0].flatMap { URL(string: $0) }

        if let url = audioURL {
            let resolvedPath = url.standardizedFileURL.path
            let allowedRoots = [
                Directories.recordings.standardizedFileURL.path,
                FileManager.default.temporaryDirectory.standardizedFileURL.path,
            ]
            guard allowedRoots.contains(where: { resolvedPath.hasPrefix($0) }) else {
                // swiftlint:disable:next line_length
                logger.error("deleteRecording: URL outside allowed directories — refusing: \(url.path, privacy: .private)")
                throw StorageError.invalidFile(reason: "audio URL points outside allowed directories")
            }
            do {
                try FileManager.default.removeItem(at: url)
            } catch {
                // swiftlint:disable:next line_length
                logger.error("Failed to remove audio file at \(url.path, privacy: .private): \(error, privacy: .private)")
                throw StorageError.deleteFailed(id: id, underlying: error)
            }
        }

        do {
            let delSeg = try prepared(DuckDBSQL.deleteSegments)
            try delSeg.bind(id.rawValue, at: 1)
            _ = try delSeg.execute()
            let delRec = try prepared(DuckDBSQL.deleteRecording)
            try delRec.bind(id.rawValue, at: 1)
            let delResult = try delRec.execute()
            guard delResult.rowCount > 0 else {
                throw StorageError.recordingNotFound(id: id)
            }
        } catch {
            throw StorageError.deleteFailed(id: id, underlying: error)
        }
    }
}

import Domain
import DuckDB
import Foundation
import Logging
import Utilities

/// Maximum JSON payload size for word_timings in bytes.
/// Blobs larger than this are dropped with a WARNING and nil is stored instead (BOUND-005).
private let wordTimingsMaxBytes = 512 * 1024 // 512 KB

public extension DuckDBWriterActor {
    func updateTranscript(id: RecordingID, transcript: TranscriptionResult) async throws {
        let profiler = HardwareBoundaryProfiler(category: "Performance")
        let token = await profiler.begin("DuckDB Save Transcript")
        defer { Task { await profiler.end(token) } }

        try guardExists(id: id)
        let wc = transcript.fullText.split(separator: " ").count
        do {
            let stmt = try prepared(DuckDBSQL.updateTranscript)
            try stmt.bind(transcript.fullText, at: 1)
            try stmt.bind(transcript.modelId.rawValue, at: 2)
            try stmt.bind(transcript.processingTime, at: 3)
            try stmt.bind(transcript.computeUnit.rawValue, at: 4)
            try stmt.bind(Int32(wc), at: 5)
            try stmt.bind(id.rawValue, at: 6)
            let result = try stmt.execute()
            guard result.rowCount > 0 else {
                throw StorageError.recordingNotFound(id: id)
            }
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
    }

    // MARK: - WordTimingsWriteRepository (task-005)

    /// Persists the word-level timing data for the given segments of a recording.
    ///
    /// Only the `word_timings` column is updated; other segment fields are unchanged.
    /// Segments with `wordTimings == nil` store NULL in the column.
    /// JSON blobs exceeding 512 KB are dropped with a WARNING and NULL is stored (BOUND-005).
    func saveWordTimings(recordingId: RecordingID, segments: [TranscriptionSegment]) async throws {
        let encoder = JSONEncoder()
        do {
            let stmt = try prepared(DuckDBSQL.saveWordTimings)
            // Use enumerated index as segment_index — matches ORDER BY segment_index ASC
            // from getSegments, which is the order AlignTranscriptUseCase passes here.
            for (idx, segment) in segments.enumerated() {
                let jsonString: String? = try encodeWordTimings(segment.wordTimings, encoder: encoder)
                try stmt.bind(jsonString, at: 1)
                try stmt.bind(recordingId.rawValue, at: 2)
                try stmt.bind(Int32(idx), at: 3)
                _ = try stmt.execute()
            }
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
    }

    // MARK: - DraftTranscriptWriteRepository (epic-182)

    /// Saves a draft transcript for a recording.
    ///
    /// Idempotent: only writes when `transcript_draft` IS NULL — first draft is preserved.
    /// If the recording does not exist, the UPDATE affects 0 rows and the call is a no-op.
    func saveDraftTranscript(draftText: String, for id: RecordingID) async throws {
        do {
            let stmt = try prepared(DuckDBSQL.saveDraftTranscript)
            try stmt.bind(draftText, at: 1)
            try stmt.bind(id.rawValue, at: 2)
            _ = try stmt.execute()
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
    }

    // MARK: - Private helpers

    private func encodeWordTimings(
        _ timings: [WordTimestamp]?,
        encoder: JSONEncoder
    ) throws -> String? {
        guard let timings else { return nil }
        let data = try encoder.encode(timings)
        guard data.count <= wordTimingsMaxBytes else {
            logger.warning(
                "word_timings JSON blob \(data.count) bytes exceeds 512 KB limit — storing nil (BOUND-005)"
            )
            return nil
        }
        return String(data: data, encoding: .utf8)
    }
}

