import Domain
import DuckDB
import Foundation

public extension DuckDBWriterActor {
    func attachDiarization(id: RecordingID, diarization: DiarizedTranscript) async throws {
        try guardExists(id: id)
        // Yield once before acquiring the transaction so other pending storage
        // operations can complete first. Task.yield() inside the transaction would
        // allow other actor methods to run on the same connection mid-transaction,
        // making them part of our transaction — wrong.
        await Task.yield()
        // UPSERT-then-trim strategy wrapped in an explicit transaction for atomicity.
        // Without BEGIN/COMMIT each statement auto-commits; a crash between UPDATE and
        // UPSERT leaves speaker_count inconsistent with the segment rows (Concern 4).
        do {
            try connection.execute("BEGIN TRANSACTION")
            do {
                let updStmt = try prepared(DuckDBSQL.updateDiarization)
                try updStmt.bind(Int32(diarization.speakerCount), at: 1)
                try updStmt.bind(diarization.processingTime, at: 2)
                try updStmt.bind(id.rawValue, at: 3)
                let updResult = try updStmt.execute()
                guard updResult.rowCount > 0 else {
                    throw StorageError.recordingNotFound(id: id)
                }

                let upsStmt = try prepared(DuckDBSQL.upsertSegment)
                for (idx, seg) in diarization.segments.enumerated() {
                    try upsStmt.bind(id.rawValue, at: 1)
                    try upsStmt.bind(Int32(idx), at: 2)
                    try upsStmt.bind(seg.text, at: 3)
                    try upsStmt.bind(seg.speakerId.rawValue, at: 4)
                    try upsStmt.bind(seg.startTime, at: 5)
                    try upsStmt.bind(seg.endTime, at: 6)
                    try upsStmt.bind(seg.confidence, at: 7)
                    let upsResult = try upsStmt.execute()
                    guard upsResult.rowCount > 0 else {
                        throw StorageError.recordingNotFound(id: id)
                    }
                }

                let trimStmt = try prepared(DuckDBSQL.deleteStaleSegments)
                try trimStmt.bind(id.rawValue, at: 1)
                try trimStmt.bind(Int32(diarization.segments.count), at: 2)
                _ = try trimStmt.execute()

                try connection.execute("COMMIT")
            } catch {
                do {
                    try connection.execute("ROLLBACK")
                } catch {
                    logger.error("attachDiarization ROLLBACK failed: \(error, privacy: .private)")
                }
                throw error
            }
        } catch {
            logger.error("attachDiarization failed: \(error, privacy: .private)")
            throw StorageError.writeFailed(underlying: error)
        }
    }

    func guardExists(id: RecordingID) throws {
        do {
            let stmt = try prepared(DuckDBSQL.selectAudioURL)
            try stmt.bind(id.rawValue, at: 1)
            let result = try stmt.execute()
            guard result.rowCount > 0 else {
                throw StorageError.recordingNotFound(id: id)
            }
        } catch let err as StorageError {
            throw err
        } catch {
            throw StorageError.readFailed(underlying: error)
        }
    }
}

