import Domain
import DuckDB
import Foundation
import Logging
import Utilities

public extension DuckDBReaderActor {
    // MARK: - WordTimings (task-005)

    /// Returns word-level timing data for each segment of a recording, ordered by segment_index.
    ///
    /// Returns an array parallel to the segments: `nil` at a position means the segment
    /// has no stored word timings (column absent, NULL, or JSON decode failed).
    /// Never throws due to a missing or malformed word_timings column — compatibility
    /// with recordings written before Epic 21 is guaranteed (COMPAT-003).
    func getWordTimings(for recordingId: RecordingID) async throws -> [[WordTimestamp]?] {
        let result: ResultSet
        do {
            let stmt = try prepared(DuckDBSQL.getWordTimings)
            try stmt.bind(recordingId.rawValue, at: 1)
            result = try stmt.execute()
        } catch {
            throw StorageError.readFailed(underlying: error)
        }
        guard result.rowCount > 0 else { return [] }
        let jsonColumn = result[1].cast(to: String.self)
        let decoder = JSONDecoder()
        var output: [[WordTimestamp]?] = []
        for i: DBInt in 0 ..< result.rowCount {
            guard let json = jsonColumn[i],
                  let data = json.data(using: .utf8) else {
                output.append(nil)
                continue
            }
            if let timings = try? decoder.decode([WordTimestamp].self, from: data) {
                output.append(timings)
            } else {
                logger.warning("word_timings JSON decode failed for recording \(recordingId.rawValue, privacy: .private) row \(i) — returning nil")
                output.append(nil)
            }
        }
        return output
    }

    // MARK: - DraftTranscriptReadRepository (epic-182)

    /// Returns the stored draft transcript for a recording, or nil if none exists.
    ///
    /// Returns nil when:
    ///   - The recording does not exist in the table.
    ///   - The `transcript_draft` column is NULL for that recording.
    /// Never throws for a missing or NULL draft — those are valid states.
    func getTranscriptDraft(for recordingId: RecordingID) async throws -> String? {
        let result: ResultSet
        do {
            let stmt = try prepared(DuckDBSQL.selectTranscriptDraft)
            try stmt.bind(recordingId.rawValue, at: 1)
            result = try stmt.execute()
        } catch {
            throw StorageError.readFailed(underlying: error)
        }
        guard result.rowCount > 0 else { return nil }
        let col = result[0].cast(to: String.self)
        return col[0]
    }

    func searchTranscripts(query: String, limit: Int? = nil, offset: Int? = nil) async throws -> [RecordingSummary] {
        let profiler = HardwareBoundaryProfiler(category: "Performance")
        let token = await profiler.begin("DuckDB Query Transcripts")
        defer { Task { await profiler.end(token) } }

        let result: ResultSet
        do {
            let stmt = try prepared(DuckDBSQL.searchTranscripts)
            let escaped = query
                .replacingOccurrences(of: "\\", with: "\\\\")
                .replacingOccurrences(of: "%", with: "\\%")
                .replacingOccurrences(of: "_", with: "\\_")
            try stmt.bind("%\(escaped)%", at: 1)
            result = try stmt.execute()
        } catch {
            throw StorageError.searchFailed(underlying: error)
        }
        return await buildSummaries(from: result)
    }
}

