import Domain
import DuckDB
import Foundation

public extension DuckDBReaderActor {
    func recordingIDsWithSummaries() async throws -> Set<RecordingID> {
        let result: ResultSet
        do {
            let stmt = try prepared(DuckDBSQL.selectSummaryRecordingIDs)
            result = try stmt.execute()
        } catch {
            throw StorageError.readFailed(underlying: error)
        }
        let column = result[0].cast(to: String.self)
        var ids = Set<RecordingID>()
        for i: DBInt in 0 ..< result.rowCount {
            if let raw = column[i] {
                ids.insert(RecordingID(raw))
            }
        }
        return ids
    }

    func getSummary(for recordingId: RecordingID) async throws -> MeetingSummary? {
        let result: ResultSet
        do {
            let stmt = try prepared(DuckDBSQL.selectSummary)
            try stmt.bind(recordingId.rawValue, at: 1)
            result = try stmt.execute()
        } catch {
            throw StorageError.readFailed(underlying: error)
        }
        guard result.rowCount > 0,
              let json = result[0].cast(to: String.self)[0],
              let data = json.data(using: .utf8) else { return nil }
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        do {
            return try decoder.decode(MeetingSummary.self, from: data)
        } catch {
            throw StorageError.readFailed(underlying: error)
        }
    }
}

