import Domain
import DuckDB
import Foundation

public extension DuckDBReaderActor {
    func getSegments(id: RecordingID) async throws -> [DiarizedSegment] {
        let result: ResultSet
        do {
            let stmt = try prepared(DuckDBSQL.selectSegments)
            try stmt.bind(id.rawValue, at: 1)
            result = try stmt.execute()
        } catch {
            throw StorageError.readFailed(underlying: error)
        }
        guard result.rowCount > 0 else { return [] }
        let texts = result[0].cast(to: String.self)
        let speakerIds = result[1].cast(to: String.self)
        let startTimes = result[2].cast(to: Double.self)
        let endTimes = result[3].cast(to: Double.self)
        let confidences = result[4].cast(to: Double.self)
        let wordTimingsColumn = result[5].cast(to: String.self)
        let decoder = JSONDecoder()
        var segments: [DiarizedSegment] = []
        for i in 0 ..< result.rowCount {
            guard let text = texts[i], let sid = speakerIds[i],
                  let st = startTimes[i], let et = endTimes[i],
                  let conf = confidences[i] else { continue }
            let wordTimings: [WordTimestamp]? = wordTimingsColumn[i].flatMap { json in
                json.data(using: .utf8).flatMap { try? decoder.decode([WordTimestamp].self, from: $0) }
            }
            segments.append(DiarizedSegment(
                text: text, speakerId: SpeakerID(rawValue: sid),
                startTime: st, endTime: et, confidence: conf,
                wordTimings: wordTimings
            ))
            if i.isMultiple(of: 100) {
                await Task.yield()
            }
        }
        return segments
    }
}

