import Domain
import DuckDB
import Foundation

extension DuckDBReaderActor {
    func rowToStoredRecording(_ result: ResultSet, row: DBInt) throws -> StoredRecording {
        let ids = result[0].cast(to: String.self)
        let dates = result[1].cast(to: String.self)
        let durations = result[2].cast(to: Double.self)
        let fileSizes = result[3].cast(to: Int64.self)
        let audioURLs = result[4].cast(to: String.self)
        let modelIds = result[5].cast(to: String.self)
        let procTimes = result[6].cast(to: Double.self)
        let compUnits = result[7].cast(to: String.self)
        let wordCounts = result[8].cast(to: Int32.self)
        let speakerCounts = result[9].cast(to: Int32.self)
        let diarTimes = result[10].cast(to: Double.self)
        let transcriptTexts = result[11].cast(to: String.self)
        // Column 12: cleaned_mic_audio_url (epic-28 / task-003; NULL on legacy rows)
        let cleanedMicURLs = result[12].cast(to: String.self)

        guard let id = ids[row], let dateStr = dates[row],
              let dur = durations[row], let fs = fileSizes[row],
              let urlStr = audioURLs[row], let mid = modelIds[row],
              let pt = procTimes[row], let cu = compUnits[row],
              let wc = wordCounts[row], let sc = speakerCounts[row],
              let dt = diarTimes[row],
              let date = try? Date(dateStr, strategy: Date.ISO8601FormatStyle(includingFractionalSeconds: true)),
              let audioURL = URL(string: urlStr)
        else {
            throw StorageError.readFailed(underlying: nil)
        }

        let computeUnit = ComputeUnit(rawValue: cu) ?? .unknown
        let cleanedMicURL = cleanedMicURLs[row].flatMap { URL(string: $0) }
        let meta = RecordingMetadata(
            id: RecordingID(id), recordedAt: date, duration: dur, fileSize: fs,
            audioURL: audioURL, transcriptURL: nil, modelId: ModelID(mid),
            processingTime: pt, computeUnit: computeUnit, wordCount: Int(wc),
            speakerCount: Int(sc), diarizationTime: dt,
            cleanedMicAudioPath: cleanedMicURL
        )

        let transcript: TranscriptionResult? = if let text = transcriptTexts[row] {
            TranscriptionResult(
                segments: [], fullText: text, processingTime: pt,
                modelId: ModelID(mid), recordedAt: date, computeUnit: computeUnit, passType: .live
            )
        } else {
            nil
        }

        return StoredRecording(metadata: meta, transcript: transcript)
    }
}

import Domain
import DuckDB
import Foundation

public extension DuckDBWriterActor {
    /// Persists a batch of InferenceMetrics entries to the inference_telemetry table.
    /// Skips entries that already exist (idempotent by id = modelId + timestamp).
    func recordTelemetry(_ entries: [InferenceMetrics]) throws {
        guard !entries.isEmpty else { return }
        do {
            let stmt = try prepared(DuckDBSQL.insertTelemetry)
            for entry in entries {
                let id = "\(entry.modelId.rawValue)-\(entry.timestamp.timeIntervalSince1970)"
                try stmt.bind(id, at: 1)
                try stmt.bind(entry.timestamp.ISO8601Format(), at: 2)
                try stmt.bind(entry.modelId.rawValue, at: 3)
                try stmt.bind(entry.audioDuration, at: 4)
                try stmt.bind(entry.inferenceDuration, at: 5)
                try stmt.bind(entry.realTimeFactor, at: 6)
                try stmt.bind(entry.confidence, at: 7)
                try stmt.bind(Int32(entry.sampleCount), at: 8)
                try stmt.bind(entry.computeUnit.rawValue, at: 9)
                try stmt.bind(entry.processMetrics?.processCpuUtilization, at: 10)
                let memMB = entry.processMetrics.map { Int64($0.processMemoryUsage / 1_048_576) }
                try stmt.bind(memMB, at: 11)
                let gpuMB = entry.processMetrics.map { Int64($0.processMlxMemoryUsage / 1_048_576) }
                try stmt.bind(gpuMB, at: 12)
                try stmt.bind(entry.processMetrics.map { Int32($0.processPageFaults) }, at: 13)
                try stmt.bind(entry.environmentMetrics?.osVersion, at: 14)
                try stmt.bind(entry.environmentMetrics?.cpuBrandString, at: 15)
                try stmt.bind(entry.environmentMetrics.map { Int32($0.physicalMemoryMB) }, at: 16)
                try stmt.bind(entry.environmentMetrics?.thermalState, at: 17)
                try stmt.bind(entry.environmentMetrics.flatMap { $0.isPluggedIn }, at: 18)
                try stmt.bind(entry.environmentMetrics.map { Int32($0.batteryStartPercentage) }, at: 19)
                _ = try stmt.execute()
            }
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
    }
}

