// MARK: - DataEraser

/// Protocol for performing a full "Delete All Data" wipe of all app-owned storage.
///
/// Conformers must delete every user-generated artifact — WAV files, the DuckDB database
/// and its backup, Keychain MCP credentials, and all UserDefaults keys — and return a
/// human-readable list of the resources that were successfully removed.
///
/// Issue #123 — Uninstall / data cleanup.
public protocol DataEraser: Sendable {
    /// Erases all app data and returns a list of resource labels that were deleted.
    ///
    /// - Returns: A list of resource names that were successfully erased (e.g. "WAV recordings").
    /// - Throws: `DataEraseError.partialFailure` if one or more resources could not be removed.
    func eraseAllData() async throws -> [String]
}

// MARK: - DataEraseError

/// Errors thrown by ``DataEraser`` implementations.
public enum DataEraseError: Error, Sendable {
    /// One or more resources could not be erased.
    /// - Parameter paths: Human-readable labels of the resources that failed.
    case partialFailure(paths: [String])
}

