/// Builds the audio capture stack for the menu bar composition root.
///
/// Pure struct with no stored state — call `build(storage:config:)` once per assembly.
@MainActor
struct AudioSubAssembler {
    /// The fully assembled audio capture stack returned by `build(storage:config:)`.
    struct Built {
        let audioCapture: CoreAudioTapCaptureActor
        let startUseCase: StartRecordingUseCase
        let autoCleanup: AutoCleanupUseCase
        let waveformVM: WaveformViewModel
        /// Acoustic echo cancellation processor shared between mic and system audio streams.
        public let aecProcessor: AECProcessorActor
        /// Factory that creates one `WAVCleanedAudioSink` per recording session.
        ///
        /// Call once at recording start, passing the session start date so the file
        /// lands in the correct year/month sub-directory. Task-003 consumes this factory
        /// to wire the sink into the AEC streaming loop.
        ///
        /// Whether to call this factory when AEC is disabled is task-003's decision;
        /// the factory itself is unconditionally provided here.
        public let cleanedAudioSinkFactory: @Sendable (Date) -> any CleanedAudioSink
    }

    /// Assembles and returns the complete audio capture stack.
    /// - Parameters:
    ///   - reader: The recording read storage actor.
    ///   - writer: The recording write storage actor.
    ///   - config: App configuration used to determine audio capture settings.
    ///   - queryContext: Optional query context use case for MCP-aware recording sessions.
    /// - Returns: Built audio components ready for use by the composition root.
    func build(
        reader: DuckDBReaderActor,
        writer: DuckDBWriterActor,
        config: AppConfig,
        queryContext: QueryContextUseCase? = nil
    ) -> Built {
        let audioCapture = CoreAudioTapCaptureActor(
            recordingDirectory: Directories.recordings,
            tapAllAudio: config.audioCapture.tapAllAudio,
            outputDeviceUID: config.audioCapture.tapAllAudio ? nil : config.audioCapture.outputDeviceUID?.rawValue,
        )
        let micCapture = MicCaptureActor()
        let startUseCase = StartRecordingUseCase(
            audioCapture: audioCapture, storage: writer, micCapture: micCapture, queryContext: queryContext,
        )
        let autoCleanup = AutoCleanupUseCase(
            reader: reader,
            writer: writer,
            activeSessionProvider: { await startUseCase.activeSessionId() },
        )
        let aecProcessor = AECProcessorActor()
        let recordingDirectory = audioCapture.recordingDirectory
        return Built(
            audioCapture: audioCapture,
            startUseCase: startUseCase,
            autoCleanup: autoCleanup,
            waveformVM: WaveformViewModel(processor: WaveformProcessor()),
            aecProcessor: aecProcessor,
            cleanedAudioSinkFactory: { sessionDate in
                WAVCleanedAudioSink(
                    recordingDirectory: recordingDirectory,
                    sessionDate: sessionDate
                )
            }
        )
    }
}

