        self.semanticTTLSeconds = semanticTTLSeconds
        self.semanticThreshold = semanticThreshold
        self.maxEntries = maxEntries
    }

    public func query(text: String) async throws -> [KnowledgeResult] {
        let pid = inner.providerID.rawValue

        var exact: [CachedResult]?
        do {
            exact = try await cache.get(query: text, providerID: pid, ttlSeconds: exactTTLSeconds)
        } catch {
            logger
                .warning(
                    // swiftlint:disable:next line_length
                    "Cache exact-match read failed, falling through to provider: \(String(reflecting: error), privacy: .private)"
                )
            exact = nil
        }
        if let exact {
            return exact.map { toKnowledgeResult($0) }
        }

        var semantic: [CachedResult]?
        do {
            semantic = try await cache.getSemantic(
                query: text, providerID: pid, matcher: matcher,
                threshold: semanticThreshold,
                ttlSeconds: semanticTTLSeconds
            )
        } catch {
            logger
                .warning(
                    // swiftlint:disable:next line_length
                    "Cache semantic read failed, falling through to provider: \(String(reflecting: error), privacy: .private)"
                )
            semantic = nil
        }
        if let semantic {
            return semantic.map { toKnowledgeResult($0) }
        }

        let results = try await inner.query(text: text)

        let toCache = results.map {
            CachedResult(
                title: $0.title, body: $0.body,
                sourceURL: $0.sourceURL?.absoluteString, providerID: $0.providerID.rawValue,
                relevanceScore: $0.relevanceScore
            )
        }

        do {
            try await cache.put(query: text, results: toCache, emptyProviderID: pid)
        } catch {
            let errDesc = String(reflecting: error)
            logger.warning("Cache write failed: \(errDesc, privacy: .private)")
        }

        do {
            try await cache.pruneIfNeeded(maxEntries: maxEntries)
        } catch {
            let errDesc = String(reflecting: error)
            logger.warning("Cache pruning failed: \(errDesc, privacy: .private)")
        }

        return results
    }

    public func isHealthy() async -> Bool {
        await inner.isHealthy()
    }

    private func toKnowledgeResult(_ cached: CachedResult) -> KnowledgeResult {
        KnowledgeResult(
            title: cached.title,
            body: cached.body,
            sourceURL: cached.sourceURL.flatMap { URL(string: $0) },
            providerID: ProviderID(cached.providerID),
            relevanceScore: cached.relevanceScore
        )
    }
}

