import Domain
import DuckDB
import Foundation
@testable import MLInfrastructure
import Testing

// MARK: - InferenceTelemetry.flushToDuckDB (task-002 / Epic 23)
//
// RED trigger: InferenceTelemetry.flushToDuckDB(_:) does not exist yet.
// Properties under test:
//   SAFE-002: Buffer only cleared on success — if writer throws, buffer unchanged
//   INV-002:  After successful flush, recentMetrics() returns []
//   IDEM-002: Flush on empty buffer → writer never called, no error
//   LIVE-001: Successful flush persists all entries to DuckDB

// MARK: - Helpers

/// Build an in-memory DuckDB stack (schema initialized by DuckDBReaderActor.init).
private func makeWriter() async throws -> DuckDBWriterActor {
    let reader = try DuckDBReaderActor(databasePath: nil)
    let db = await reader.database
    return try DuckDBWriterActor(database: db)
}

private func makeMetrics(
    modelId: String = "test-model",
    ts: Double = 1000
) -> InferenceMetrics {
    InferenceMetrics(
        modelId: ModelID(modelId),
        audioDuration: 60.0,
        inferenceDuration: 0.5,
        realTimeFactor: 120.0,
        confidence: 0.9,
        sampleCount: 960_000,
        computeUnit: .cpuAndNeuralEngine,
        timestamp: Date(timeIntervalSince1970: ts)
    )
}

// MARK: - Test Suite

@Suite("InferenceTelemetry.flushToDuckDB (task-002)", .serialized)
struct InferenceTelemetryFlushTests {

    // MARK: T1: INV-002 — flush clears buffer on success

    @Test("INV-002: successful flush leaves recentMetrics empty")
    func flushClearsBufferOnSuccess() async throws {
        let telemetry = InferenceTelemetry()
        await telemetry.record(makeMetrics(ts: 1000))
        await telemetry.record(makeMetrics(ts: 1001))
        await telemetry.record(makeMetrics(ts: 1002))

        let writer = try await makeWriter()
        try await telemetry.flushToDuckDB(writer)

        let remaining = await telemetry.recentMetrics(limit: 1000)
        #expect(remaining.isEmpty, "Buffer must be empty after successful flush (INV-002)")
    }

    // MARK: T2: SAFE-002 — buffer preserved when writer fails

    @Test("SAFE-002: buffer unchanged when writer throws")
    func flushPreservesBufferOnWriterFailure() async throws {
        let telemetry = InferenceTelemetry()
        await telemetry.record(makeMetrics(ts: 2000))
        await telemetry.record(makeMetrics(ts: 2001))

        // Force writer failure by creating a writer against a broken DB (no schema table).
        // We create a second in-memory DB (no schema setup) so inference_telemetry table
        // does not exist — any INSERT will throw.
        let brokenDB = try Database(store: .inMemory)
        let brokenWriter = try DuckDBWriterActor(database: brokenDB)

        // The flush must throw (table doesn't exist), and the buffer must remain intact.
        var caughtError: Error?
        do {
            try await telemetry.flushToDuckDB(brokenWriter)
        } catch {
            caughtError = error
        }

        #expect(caughtError != nil, "Expected flushToDuckDB to throw when writer fails (SAFE-002)")
        let remaining = await telemetry.recentMetrics(limit: 1000)
        #expect(remaining.count == 2, "Buffer must be unchanged (count=2) when writer throws (SAFE-002)")
    }

    // MARK: T3: IDEM-002 — flush on empty buffer is a no-op

    @Test("IDEM-002: flush on empty buffer completes without error")
    func flushEmptyBufferIsNoOp() async throws {
        let telemetry = InferenceTelemetry()
        // Buffer is empty — flush should be a no-op and not throw.
        let writer = try await makeWriter()
        try await telemetry.flushToDuckDB(writer)

        // Buffer is still empty — trivially true, but ensures no crash
        let remaining = await telemetry.recentMetrics(limit: 1000)
        #expect(remaining.isEmpty, "Buffer must stay empty after no-op flush (IDEM-002)")
    }

    // MARK: T4: LIVE-001 — all entries persisted to DuckDB

    @Test("LIVE-001: all flushed entries are queryable in inference_telemetry")
    func flushWritesAllEntriesToDuckDB() async throws {
        let telemetry = InferenceTelemetry()
        await telemetry.record(makeMetrics(ts: 3000))
        await telemetry.record(makeMetrics(ts: 3001))
        await telemetry.record(makeMetrics(ts: 3002))

        // Use a reader to share the same in-memory DB so we can verify the rows.
        let reader = try DuckDBReaderActor(databasePath: nil)
        let db = await reader.database
        let writer = try DuckDBWriterActor(database: db)

        try await telemetry.flushToDuckDB(writer)

        let result = try await reader.connection.query("SELECT COUNT(*) FROM inference_telemetry")
        let col = result[0].cast(to: Int64.self)
        let count = Int(col[0] ?? 0)
        #expect(count == 3, "Expected 3 rows in inference_telemetry after flush, got \(count) (LIVE-001)")
    }
}

