import Domain
import Foundation
@testable import MLInfrastructure
import Testing

@Suite("CachingContextProvider")
struct CachingContextProviderTests {
    private func makeStore() throws -> DuckDBContextCache {
        try DuckDBContextCache(databasePath: nil)
    }

    // MARK: - Cache miss → delegates to inner provider

    @Test("cache miss queries inner provider and stores result")
    func cacheMissDelegatesToInner() async throws {
        let inner = MockContextProvider(providerID: ProviderID("test-provider"))
        await inner.setResults([
            KnowledgeResult(
                title: "Lambda Docs",
                body: "Serverless compute",
                providerID: ProviderID("test-provider"),
                relevanceScore: 0.9
            ),
        ])
        let cache = try makeStore()
        let provider = CachingContextProvider(inner: inner, cache: cache, ttlSeconds: 300)

        let results = try await provider.query(text: "Lambda cold starts")

        #expect(results.count == 1)
        #expect(results[0].title == "Lambda Docs")
        let innerCalls = await inner.queryCallCount
        #expect(innerCalls == 1)
    }

    // MARK: - Cache hit → skips inner provider

    @Test("cache hit returns stored result without querying inner")
    func cacheHitSkipsInner() async throws {
        let inner = MockContextProvider(providerID: ProviderID("test-provider"))
        await inner.setResults([
            KnowledgeResult(
                title: "DynamoDB Docs",
                body: "NoSQL at scale",
                providerID: ProviderID("test-provider"),
                relevanceScore: 0.85
            ),
        ])
        let cache = try makeStore()
        let provider = CachingContextProvider(inner: inner, cache: cache, ttlSeconds: 300)

