            query: "how to set Lambda function timeout",
            providerID: "aws",
            matcher: matcher,
            threshold: 0.1,
            ttlSeconds: 300
        )

        #expect(results != nil)
        #expect(results?.first?.title == "Lambda Config", "Lambda timeout query should match Lambda entry, not S3")
    }
}

