import Domain
import Foundation
import GRDB
import Logging

public actor GRDBStorageActor: AdminExecutable {
    public let dbPool: DatabasePool
    let logger = AppLogger.for(category: "GRDBStorage")

    public init(databasePath: URL?) throws {
        if let path = databasePath {
            try FileManager.default.createDirectory(
                at: path.deletingLastPathComponent(),
                withIntermediateDirectories: true
            )
            dbPool = try DatabasePool(path: path.path)
        } else {
            dbPool = try DatabasePool(path: ":memory:")
        }
        try GRDBMigrations.migrator().migrate(dbPool)
        if let path = databasePath {
            try FileManager.default.setAttributes(
                [.posixPermissions: 0o600 as NSNumber],
                ofItemAtPath: path.path
            )
        }
    }

    public init() throws {
        let dbDir = Directories.appSupport
        try Directories.ensureDirectory(at: dbDir)
        let dbURL = dbDir.appendingPathComponent(
            AppConstants.Paths.databaseFileName
                .replacingOccurrences(of: ".duckdb", with: ".sqlite")
        )
        try self.init(databasePath: dbURL)
    }

    // MARK: - AdminExecutable

    public func adminExecute(_ sql: String) async throws {
        try await dbPool.write { db in
            try db.execute(sql: sql)
        }
    }

    // MARK: - Backup

    public func backupDatabase(to destination: URL) async throws {
        try await dbPool.write { db in
            try db.execute(sql: "PRAGMA wal_checkpoint(TRUNCATE)")
        }
        guard let sourcePath = dbPool.path.flatMap({ URL(fileURLWithPath: $0) }) else {
            throw StorageError.writeFailed(underlying: nil)
        }
        let fm = FileManager.default
        if fm.fileExists(atPath: destination.path) {
            try fm.removeItem(at: destination)
        }
        try fm.copyItem(at: sourcePath, to: destination)
    }

    public func backupDatabase(source: URL, to destination: URL) async throws {
        let fm = FileManager.default
        if fm.fileExists(atPath: destination.path) {
            try fm.removeItem(at: destination)
        }
        try fm.copyItem(at: source, to: destination)
    }
}

// MARK: - DatabasePool path helper

extension DatabasePool {
    var path: String? {
        let p = try? read { db in db.path }
        guard let p, p != ":memory:", p != "" else { return nil }
        return p
    }
}

import Accelerate
import Domain
import Foundation
import GRDB
import Logging
@preconcurrency import NaturalLanguage

public struct CachedResult: Sendable {
    public let title: String
    public let body: String
    public let sourceURL: String?
    public let providerID: String
    public let relevanceScore: Double
}

public actor GRDBContextCache {
    private let dbPool: DatabasePool
    private let logger = AppLogger.for(category: "ContextCache")
    private var nlEmbedding: NLEmbedding?

    public init(databasePath: URL?) throws {
        if let path = databasePath {
            try FileManager.default.createDirectory(
                at: path.deletingLastPathComponent(),
                withIntermediateDirectories: true
            )
            dbPool = try DatabasePool(path: path.path)
        } else {
            dbPool = try DatabasePool(path: ":memory:")
        }
        try GRDBMigrations.migrator().migrate(dbPool)
    }

    public func get(query: String, providerID: String, ttlSeconds: Int) async throws -> [CachedResult]? {
        try await dbPool.read { db in
            let rows = try Row.fetchAll(
                db, sql: GRDBSQL.selectCached,
                arguments: [query, providerID, ttlSeconds]
            )
            guard !rows.isEmpty else { return nil }
            return rows.map { row in
                CachedResult(
                    title: row["title"] ?? "",
                    body: row["body"] ?? "",
                    sourceURL: row["source_url"],
                    providerID: row["provider_id"] ?? "",
                    relevanceScore: row["relevance_score"] ?? 0
                )
            }
        }
    }

    public func put(query: String, results: [CachedResult], emptyProviderID: String = "") async throws {
        let providerIDsToEvict: Set<String> = results.isEmpty
            ? (emptyProviderID.isEmpty ? [] : [emptyProviderID])
            : Set(results.map(\.providerID))

        let embeddingBlob: Data? = await embeddingVector(for: query).map { vector in
            vector.withUnsafeBufferPointer { Data(buffer: $0) }
        }

        try await dbPool.write { db in
            for pid in providerIDsToEvict {
                try db.execute(sql: GRDBSQL.deleteCached, arguments: [query, pid])
            }

            guard !results.isEmpty else {
                try db.execute(sql: GRDBSQL.insertCached, arguments: [
                    query, "", "", nil as String?, emptyProviderID, 0.0, embeddingBlob,
                ])
                return
            }

            for result in results {
                try db.execute(sql: GRDBSQL.insertCached, arguments: [
                    query, result.title, result.body, result.sourceURL,
                    result.providerID, result.relevanceScore, embeddingBlob,
                ])
            }
        }
    }

    public func getSemantic(
        query: String, providerID: String,
        matcher: NLEmbedding,
        threshold: Double,
        ttlSeconds: Int
    ) async throws -> [CachedResult]? {
        let rows: [Row] = try await dbPool.read { db in
            try Row.fetchAll(db, sql: GRDBSQL.selectDistinctQueriesWithEmbeddings, arguments: [providerID])
        }
        guard !rows.isEmpty else { return nil }

        guard let queryVector = await embeddingVector(for: query) else {
            var bestMatch: (query: String, score: Double)?
            for row in rows {
                guard let cached: String = row["query_text"] else { continue }
                let score = matcher.similarity(between: query, and: cached)
                if score >= threshold, bestMatch.map({ score > $0.score }) ?? true {
                    bestMatch = (cached, score)
                }
            }
            guard let match = bestMatch else { return nil }
            return try await get(query: match.query, providerID: providerID, ttlSeconds: ttlSeconds)
        }

        let preFilterThreshold = max(0.0, threshold - 0.3)
        var candidates: [(query: String, score: Double)] = []

        for row in rows {
            guard let cached: String = row["query_text"],
                  let blob = row["embedding"] as? Data else { continue }
            let storedVector: [Double] = blob.withUnsafeBytes {
                Array($0.bindMemory(to: Double.self))
            }
            let coarse = cosineSimilarity(queryVector, storedVector)
            if coarse >= preFilterThreshold {
                candidates.append((cached, coarse))
            }
        }

        guard !candidates.isEmpty else { return nil }
        candidates.sort { $0.score > $1.score }
        let best = candidates.first!
        guard best.score >= threshold else { return nil }
        return try await get(query: best.query, providerID: providerID, ttlSeconds: ttlSeconds)
    }

    public func pruneIfNeeded(maxEntries: Int) async throws {
        try await dbPool.write { db in
            let count = try Int.fetchOne(db, sql: GRDBSQL.countCacheEntries) ?? 0
            guard count > maxEntries else { return }
            let excess = count - maxEntries
            try db.execute(sql: GRDBSQL.pruneCacheOldest, arguments: [excess])
        }
    }

    public func entryCount() async throws -> Int {
        try await dbPool.read { db in
            try Int.fetchOne(db, sql: GRDBSQL.countCacheEntries) ?? 0
        }
    }

    // MARK: - Embedding helpers

    private func embeddingVector(for text: String) async -> [Double]? {
        if nlEmbedding == nil {
            nlEmbedding = await Task.detached(priority: .utility) {
                NLEmbedding.sentenceEmbedding(for: .english)
            }.value
        }
        return nlEmbedding?.vector(for: text)
    }

    private func cosineSimilarity(_ a: [Double], _ b: [Double]) -> Double {
        guard a.count == b.count, !a.isEmpty else { return 0 }
        let dot = vDSP.dot(a, b)
        let magA = vDSP.sumOfSquares(a).squareRoot()
        let magB = vDSP.sumOfSquares(b).squareRoot()
        guard magA > 0, magB > 0 else { return 0 }
        return dot / (magA * magB)
    }
}

import Domain
import Foundation
import GRDB
import Logging

public actor GRDBCommitmentStore: CommitmentStore {
    private let dbPool: DatabasePool
    private let logger = AppLogger.for(category: "GRDBCommitments")

    public init(databasePath: URL?) throws {
        if let path = databasePath {
            try FileManager.default.createDirectory(
                at: path.deletingLastPathComponent(),
                withIntermediateDirectories: true
            )
            dbPool = try DatabasePool(path: path.path)
        } else {
            dbPool = try DatabasePool(path: ":memory:")
        }
        try GRDBMigrations.migrator().migrate(dbPool)
    }

    // MARK: - CommitmentStore

    public func record(_ commitment: Commitment) async throws {
        let iso = commitment.createdAt.formatted(Date.ISO8601FormatStyle(includingFractionalSeconds: true))
        let dueDateStr: String? = commitment.dueDate.map {
            $0.formatted(.iso8601.year().month().day())
        }
        do {
            try await dbPool.write { db in
                try db.execute(sql: GRDBSQL.insertCommitment, arguments: [
                    commitment.id.rawValue, commitment.description, commitment.assignee,
                    dueDateStr, commitment.status.rawValue, commitment.meetingId.rawValue, iso,
                ])
            }
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
        logger.info("Recorded commitment \(commitment.id, privacy: .private)")
    }

    public func openCommitments() async throws -> [Commitment] {
        do {
            return try await dbPool.read { db in
                let rows = try Row.fetchAll(db, sql: GRDBSQL.selectOpenCommitments)
                return Self.decodeCommitments(from: rows)
            }
        } catch {
            throw StorageError.readFailed(underlying: error)
        }
    }

    public func commitments(for meetingId: RecordingID) async throws -> [Commitment] {
        do {
            return try await dbPool.read { db in
                let rows = try Row.fetchAll(db, sql: GRDBSQL.selectCommitmentsForMeeting, arguments: [meetingId.rawValue])
                return Self.decodeCommitments(from: rows)
            }
        } catch {
            throw StorageError.readFailed(underlying: error)
        }
    }

    // MARK: - Private

    private static func decodeCommitments(from rows: [Row]) -> [Commitment] {
        rows.compactMap { row -> Commitment? in
            guard let id: String = row["id"],
                  let desc: String = row["description"],
                  let statusRaw: String = row["status"],
                  let mid: String = row["meeting_id"],
                  let createdStr: String = row["created_at"],
                  let status = CommitmentStatus(rawValue: statusRaw),
                  let createdAt = try? Date(
                      createdStr,
                      strategy: Date.ISO8601FormatStyle(includingFractionalSeconds: true)
                  ) else { return nil }
            let assignee: String? = row["assignee"]
            let dueDateStr: String? = row["due_date"]
            let dueDate = dueDateStr.flatMap { try? Date($0, strategy: .iso8601.year().month().day()) }
            return Commitment(
                id: CommitmentID(id), description: desc,
                assignee: assignee, dueDate: dueDate,
                status: status, meetingId: RecordingID(mid),
                createdAt: createdAt
            )
        }
    }
}

import Domain
import Foundation
import Logging

public enum JSONMigrationHelper {
    private static let logger = AppLogger.for(category: "Migration")

    public static func migrate(from jsonBaseDir: URL, reader: some RecordingReadRepository, writer: some RecordingWriteRepository) async throws -> Int {
        let fm = FileManager.default
        guard fm.fileExists(atPath: jsonBaseDir.path) else { return 0 }

        let enumerator = fm.enumerator(
            at: jsonBaseDir,
            includingPropertiesForKeys: [.isRegularFileKey],
            options: [.skipsHiddenFiles]
        )

        var migrated = 0
        let decoder = JSONDecoder()
        while let url = enumerator?.nextObject() as? URL {
            guard url.pathExtension == "json" else { continue }
            do {
                let data = try await Task.detached(priority: .utility) { try Data(contentsOf: url) }.value
                let metadata = try decoder.decode(RecordingMetadata.self, from: data)

                do {
                    _ = try await reader.getRecording(id: metadata.id)
                    continue // already migrated — skip
                } catch StorageError.recordingNotFound {
                    // not yet in DB — proceed with import
                }

                let audioFile = AudioFile(
                    id: metadata.id,
                    url: metadata.audioURL,
                    duration: metadata.duration,
                    fileSize: metadata.fileSize,
                    recordedAt: metadata.recordedAt
                )
                _ = try await writer.saveRecording(audioFile)
                migrated += 1
                logger.info("Migrated \(metadata.id, privacy: .private) from \(url.lastPathComponent, privacy: .public)")
            } catch let decodeError as DecodingError {
                logger
                    .warning(
                        // swiftlint:disable:next line_length
                        "Skipped \(url.lastPathComponent, privacy: .private) — corrupt JSON: \(decodeError, privacy: .private)"
                    )
            } catch let storageError as StorageError {
                // DB write failure is more serious than a corrupt source file —
                // log at .error level so it surfaces in operator dashboards
                logger
                    .error(
                        // swiftlint:disable:next line_length
                        "Migration write failed for \(url.lastPathComponent, privacy: .private): \(storageError, privacy: .private)"
                    )
            } catch let cocoaError as CocoaError where cocoaError.code == .fileReadNoPermission {
                logger
                    .error(
                        // swiftlint:disable:next line_length
                        "Permission denied reading \(url.lastPathComponent, privacy: .private): \(cocoaError, privacy: .private)"
                    )
            } catch {
                logger
                    .warning(
                        // swiftlint:disable:next line_length
                        "Skipped \(url.lastPathComponent, privacy: .private) — \(type(of: error), privacy: .private): \(error, privacy: .private)"
                    )
            }
        }

        logger.info("Migration complete: \(migrated, privacy: .private) recordings imported")
        return migrated
    }
}

import Domain
import Foundation
@testable import MLInfrastructure
import Testing

/// Integration test skeleton for MCP providers (F21 E6).
///
/// These tests require real file-system and DuckDB access.
/// They are gated behind RUN_INTEGRATION_TESTS=1 so they never block CI.
///
/// Run with:
///   RUN_INTEGRATION_TESTS=1 swift test --filter "MCPProviderIntegration"
private let integrationEnabled = ProcessInfo.processInfo.environment["RUN_INTEGRATION_TESTS"] == "1"

@Suite("MCP Provider Integration (E6)", .serialized)
struct MCPProviderIntegrationTests {

    // MARK: - Helpers

    private func makeTempVault() throws -> URL {
        let dir = FileManager.default.temporaryDirectory
            .appendingPathComponent("mcp-integration-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir
    }

    // MARK: - AC-E6a: ObsidianProvider returns file content under happy path

    @Test(
        "E6a: ObsidianProvider returns markdown file content from temp vault",
        .enabled(if: integrationEnabled, "Set RUN_INTEGRATION_TESTS=1 to run this test")
    )
    func obsidianProviderHappyPath() async throws {
        let vault = try makeTempVault()
        defer { try? FileManager.default.removeItem(at: vault) }

        let content = "# Lambda Architecture\nEvent-driven serverless compute patterns."
        try content.write(
            to: vault.appendingPathComponent("lambda-notes.md"),
            atomically: true,
            encoding: .utf8
        )

        let provider = ObsidianProvider(vaultPath: vault)
        let results = try await provider.query(text: "Lambda")

        #expect(results.count >= 1, "ObsidianProvider must return at least one result for matching content")
        let match = try #require(results.first { $0.title.lowercased().contains("lambda") })
        #expect(
            match.body.contains("serverless") || match.body.contains("Lambda"),
            "Result body must contain content from the markdown file"
        )
        #expect(match.providerID == ProviderID("obsidian"))
    }

    // MARK: - AC-E6b: CachingContextProvider serves second query from cache

    @Test(
        "E6b: CachingContextProvider second identical query is a cache hit (inner not called again)",
        .enabled(if: integrationEnabled, "Set RUN_INTEGRATION_TESTS=1 to run this test")
    )
    func cachingContextProviderCacheHit() async throws {
        let vault = try makeTempVault()
        defer { try? FileManager.default.removeItem(at: vault) }

        try "# Kubernetes\nContainer orchestration platform.".write(
            to: vault.appendingPathComponent("k8s.md"),
            atomically: true,
            encoding: .utf8
        )

        let obsidian = ObsidianProvider(vaultPath: vault)

        // Use in-memory GRDB cache so the test is hermetic.
        let cache = try GRDBContextCache(databasePath: nil)
        let cachingProvider = CachingContextProvider(
            inner: obsidian,
            cache: cache,
            ttlSeconds: 3600
        )

        // First query: cache miss — must hit ObsidianProvider.
        let firstResults = try await cachingProvider.query(text: "Kubernetes")
        #expect(firstResults.count >= 1, "First query must return results from ObsidianProvider")

        // Second identical query: cache hit — entry count must not change (no new insert).
        let entriesBeforeSecond = try await cache.entryCount()
        let secondResults = try await cachingProvider.query(text: "Kubernetes")
        let entriesAfterSecond = try await cache.entryCount()

        #expect(
            secondResults.count == firstResults.count,
            "Second query must return the same number of results as the first"
        )
        #expect(
            entriesAfterSecond == entriesBeforeSecond,
            "Cache entry count must not change on a cache hit — second query served from cache"
        )
    }
}
